from decimal import Decimal

LIGHT_KG = Decimal("0.500")
MEDIUM_KG = Decimal("2.000")


def average_weight_kg(order):
    units = sum(item.qty for item in order.items)
    if units == 0:
        return "0.000"
    # Exact integer arithmetic in milligrams; round half to even.
    total_mg = sum(int(Decimal(item.line_weight_kg()) * 1000) for item in order.items)
    quotient, remainder = divmod(total_mg, units)
    if 2 * remainder > units or (2 * remainder == units and quotient % 2 == 1):
        quotient += 1
    return f"{quotient // 1000}.{quotient % 1000:03d}"


def heaviest(order, n=3):
    return sorted(order.items, key=lambda item: (-Decimal(item.weight_kg), item.sku))[:n]


def weight_bands(order):
    bands = {"light": 0, "medium": 0, "heavy": 0}
    for item in order.items:
        weight = Decimal(item.weight_kg)
        if weight <= LIGHT_KG:
            bands["light"] += item.qty
        elif weight <= MEDIUM_KG:
            bands["medium"] += item.qty
        else:
            bands["heavy"] += item.qty
    return bands

